			Fields: map[string]runtimecontracts.ExpressionValue{
				"revision_count": runtimecontracts.CELExpression("entity.revision_count"),
			},
		},
	}, workflowTriggerContext{
		Event: trigger,
		State: state,
	}, false)
	if err != nil {
		t.Fatalf("executeNodeContractHandler: %v", err)
	}
